//! Commands the frontend calls. Typed bindings are generated by tauri-specta.
//!
//! These are thin: parameter marshalling and a call into a crate. Anything
//! resembling logic belongs in a crate where it can be tested.

use crate::AppState;
use aloud_store::{timings::Span, Settings, Stats};
use tauri::{AppHandle, State};
use tauri_specta::Event;

/// Commands must return a `Result` the frontend can read; anyhow's error is
/// not serializable, so errors cross the boundary as strings.
type CmdResult<T> = Result<T, String>;

fn to_string_err<T>(result: anyhow::Result<T>) -> CmdResult<T> {
    result.map_err(|e| format!("{e:#}"))
}

#[tauri::command]
#[specta::specta]
pub fn get_settings(state: State<'_, AppState>) -> Settings {
    state.settings.lock().map(|s| s.clone()).unwrap_or_default()
}

/// Persists settings and applies them to the running app.
#[tauri::command]
#[specta::specta]
pub fn update_settings(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    settings: Settings,
) -> CmdResult<()> {
    to_string_err(settings.save())?;

    // Push the hotkey slice into the live config the listener reads, so a
    // rebind takes effect on the next key event rather than at next launch.
    if let Ok(mut config) = state.hotkey_config.lock() {
        *config = settings.hotkeys.clone();
    }

    // Applied live rather than at next launch: a toggle that appears to do
    // nothing reads as broken, and the user would toggle it again.
    crate::tray::set_visible(&app, settings.show_menu_bar_icon);

    let mut current = state
        .settings
        .lock()
        .map_err(|_| "settings lock poisoned")?;
    *current = settings;
    Ok(())
}

#[tauri::command]
#[specta::specta]
pub fn get_stats(state: State<'_, AppState>) -> StatsView {
    let stats = state.pipeline.stats();
    StatsView {
        time_saved_seconds: stats.time_saved_seconds(),
        stats,
    }
}

/// [`Stats`] plus the values derived from it.
///
/// Derived rather than stored: `Stats` is written to disk after every
/// dictation, and persisting a computed field would let the file disagree
/// with the formula the moment the formula changed.
///
/// It crosses the boundary at all so the frontend does not re-derive it. The
/// 40 wpm rule lived in both `stats.rs` and `App.tsx`, with the constant
/// inlined on the TS side — changing it in Rust would have silently left the
/// main window disagreeing with the tray menu.
#[derive(serde::Serialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct StatsView {
    #[serde(flatten)]
    pub stats: Stats,
    pub time_saved_seconds: f64,
}

#[tauri::command]
#[specta::specta]
pub fn search_notes(query: String) -> CmdResult<Vec<aloud_notes::SearchResult>> {
    let dir = to_string_err(aloud_notes::directory())?;
    Ok(aloud_notes::search(&query, &aloud_notes::all_notes(&dir)))
}

/// Newest notes, for the empty-query state.
#[tauri::command]
#[specta::specta]
pub fn recent_notes(limit: u32) -> CmdResult<Vec<aloud_notes::Note>> {
    let dir = to_string_err(aloud_notes::directory())?;
    let mut notes = aloud_notes::all_notes(&dir);
    notes.truncate(limit as usize);
    Ok(notes)
}

/// The shipped cleanup prompt and the date it last changed.
///
/// Both halves serve the Prompts pane: the text backs "View Default", and the
/// version is what `Settings::seen_prompt_version` is compared against to
/// decide whether a user who forked the prompt is missing an improvement.
#[derive(serde::Serialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct DefaultPrompt {
    pub text: String,
    pub version: String,
}

#[tauri::command]
#[specta::specta]
pub fn default_prompt() -> DefaultPrompt {
    DefaultPrompt {
        text: aloud_llm::prompts::CLEANUP.to_string(),
        version: aloud_llm::prompts::CLEANUP_VERSION.to_string(),
    }
}

/// Runs a prompt against a sample without a dictation, for the Prompts pane.
///
/// Everything but the prompt comes from live settings, so what this shows is
/// what the next dictation would do — including the model, the fallback and
/// the vocabulary, all of which change the answer.
///
/// The two ways this can appear broken while working correctly are answered
/// here rather than left as a puzzle: cleanup skips anything at or under
/// [`aloud_llm::cleanup::MIN_WORDS`] and returns it verbatim, which reads as a
/// prompt that did nothing; and a filler-only sample legitimately produces no
/// text at all, which reads as a blank panel.
#[tauri::command]
#[specta::specta]
pub async fn test_prompt(
    state: State<'_, AppState>,
    prompt: String,
    sample: String,
) -> CmdResult<String> {
    let settings = state.settings.lock().map(|s| s.clone()).unwrap_or_default();

    if sample.trim().is_empty() {
        return Err("Type a sample transcript to run the prompt against.".into());
    }
    if aloud_llm::cleanup::is_too_short(&sample) {
        return Err(format!(
            "Sample is too short. Dictations of {} words or fewer skip cleanup entirely \
             and are pasted as spoken, so the prompt would never run. Add a few more words.",
            aloud_llm::cleanup::MIN_WORDS
        ));
    }
    if settings.groq_api_key.trim().is_empty() {
        return Err("No API key is configured, so there is nothing to run against.".into());
    }

    let options = aloud_llm::cleanup::Options {
        api_key: &settings.groq_api_key,
        base_url: &settings.base_url,
        model: &settings.post_processing_model,
        fallback: Some(settings.fallback_model.as_str()),
        custom_prompt: &prompt,
        vocabulary: &settings.vocabulary,
        output_language: &settings.output_language,
    };
    let cleaned = to_string_err(aloud_llm::cleanup::clean(options, &sample).await)?;

    if cleaned.trim().is_empty() {
        return Ok(
            "(nothing — the prompt judged the sample to be filler and asked for an \
             empty paste. That is the EMPTY sentinel doing its job, not a failure.)"
                .into(),
        );
    }
    Ok(cleaned)
}

#[tauri::command]
#[specta::specta]
pub fn input_devices() -> CmdResult<Vec<aloud_audio::AudioDevice>> {
    to_string_err(aloud_audio::input_devices())
}

/// Installed apps, to fill the App Rules picker. Empty on Windows (no scan
/// there yet); the custom-match field still works everywhere.
///
/// `async` is load-bearing: Tauri runs a non-async command on the main thread,
/// so the scan froze the whole webview rather than merely showing a spinner.
/// The work is blocking (process spawns), hence `spawn_blocking` rather than
/// parking an async worker on it.
///
/// Fallible so a scan that dies is distinguishable from a machine with no
/// applications — an empty picker with no error reads as the former.
#[tauri::command]
#[specta::specta]
pub async fn installed_apps() -> CmdResult<Vec<aloud_selection::InstalledApp>> {
    tauri::async_runtime::spawn_blocking(aloud_selection::installed_apps)
        .await
        .map_err(|e| format!("listing installed apps: {e}"))
}

/// Whether the OS lets us listen for keys. False on macOS until the user
/// grants Accessibility permission.
#[tauri::command]
#[specta::specta]
pub fn hotkeys_permitted() -> bool {
    aloud_hotkey::is_permitted()
}

/// Plays the start chime, so the volume slider can be judged by ear rather
/// than by guessing at a number.
#[tauri::command]
#[specta::specta]
pub fn preview_sound(volume: f32) {
    crate::sound::play(crate::sound::Chime::Start, true, volume);
}

/// Whether the OS launches Aloud at login. The autostart plugin owns this
/// state (a login item / registry key), not settings.json — storing a copy
/// would drift the moment the user changed it outside the app.
#[tauri::command]
#[specta::specta]
pub fn launch_at_login(app: AppHandle) -> CmdResult<bool> {
    use tauri_plugin_autostart::ManagerExt;
    to_string_err(app.autolaunch().is_enabled().map_err(Into::into))
}

/// One connectable service, for the Connectors pane.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct Connector {
    pub slug: String,
    pub name: String,
    pub logo: String,
    pub description: String,
    #[specta(type = specta_typescript::Number)]
    pub tools_count: u32,
    pub connected: bool,
    pub connection_id: Option<String>,
}

/// Composio responses held between opens of the Connectors pane. The policy
/// (credential scoping, single-flight revalidation) lives in `aloud_agent`.
pub type ConnectorCache = std::sync::Arc<aloud_agent::ResponseCache<Connector>>;

/// The configured Composio key, or the error the pane should show.
///
/// Read before touching the cache: it doubles as the cache's scope, so an
/// account swap misses rather than serving the previous account's data.
fn api_key(state: &State<'_, AppState>) -> CmdResult<String> {
    let key = state
        .settings
        .lock()
        .map(|s| s.composio_api_key.clone())
        .unwrap_or_default();
    if key.trim().is_empty() {
        return Err("Connectors are unavailable — no Composio credential is configured".into());
    }
    Ok(key)
}

fn client(key: &str) -> CmdResult<aloud_agent::ComposioClient> {
    to_string_err(aloud_agent::ComposioClient::new(key))
}

fn to_connector(toolkit: aloud_agent::Toolkit) -> Connector {
    Connector {
        slug: toolkit.slug,
        name: toolkit.name,
        logo: toolkit.logo,
        description: toolkit.description,
        tools_count: toolkit.tools_count,
        connected: toolkit.connected,
        connection_id: toolkit.connection_id,
    }
}

/// Fetches the connected toolkits and maps them to the pane's shape.
///
/// The pane lists services, not tool names, so this stops at the toolkit
/// metadata — which is one request, not one per connected service.
async fn fetch_connected(composio: &aloud_agent::ComposioClient) -> anyhow::Result<Vec<Connector>> {
    Ok(composio
        .connected_toolkits()
        .await?
        .into_iter()
        .map(to_connector)
        .collect())
}

/// Refetches in the background and pushes the result only if it changed.
///
/// The cache decides both whether to run at all (one revalidation in flight at
/// a time — every window focus asks for one) and whether the result is news.
fn revalidate(app: AppHandle, key: String, cache: ConnectorCache) {
    if !cache.begin_revalidation() {
        return;
    }
    tauri::async_runtime::spawn(async move {
        let fetched = match client(&key) {
            Ok(composio) => fetch_connected(&composio).await.ok(),
            Err(_) => None,
        };
        // Release the claim on the failure path too, or nothing revalidates
        // again for the life of the process.
        let Some(fresh) = fetched else {
            cache.finish_revalidation(&key, None);
            return;
        };
        if cache.finish_revalidation(&key, Some(fresh.clone())) {
            let _ = crate::ConnectorsUpdated(fresh).emit(&app);
        }
    });
}

/// Fills the connector cache in the background at startup.
///
/// Skipped entirely without a Composio key: there is nothing to fetch, and a
/// launch should not touch the network for a feature the user has not set up.
/// Failure is silent — this is a warm-up, and the pane still fetches for real.
pub fn warm_connectors(app: AppHandle) {
    use tauri::Manager;

    let state = app.state::<AppState>();
    let Ok(key) = api_key(&state) else {
        return;
    };
    let cache = state.connectors.clone();
    tauri::async_runtime::spawn(async move {
        let Ok(composio) = client(&key) else {
            return;
        };
        if let Ok(fresh) = fetch_connected(&composio).await {
            cache.store_primary(&key, fresh);
        }
    });
}

/// Connected toolkits, each with the tools the agent will actually offer.
///
/// Stale-while-revalidate: a warm cache paints the pane with no network at
/// all, and a background refresh pushes `connectors-updated` if anything moved.
/// A plain TTL would be wrong here — OAuth finishes in the browser, so the user
/// comes back expecting a service that was connected seconds ago.
#[tauri::command]
#[specta::specta]
pub async fn list_connectors(
    app: AppHandle,
    state: State<'_, AppState>,
) -> CmdResult<Vec<Connector>> {
    let key = api_key(&state)?;
    let cache = state.connectors.clone();

    if let Some(hit) = cache.primary(&key) {
        revalidate(app, key, cache);
        return Ok(hit);
    }

    // Cold: the only path that makes the pane wait on Composio.
    let fresh = to_string_err(fetch_connected(&client(&key)?).await)?;
    cache.store_primary(&key, fresh.clone());
    Ok(fresh)
}

/// Toolkits matching `query`, for the add-a-connector search.
///
/// Cached per query: the pane fires the empty query on every mount to fill
/// "Add a connector", and re-typing a query is common. Composio's catalogue
/// does not move within a session, so this is served from memory once seen.
#[tauri::command]
#[specta::specta]
pub async fn search_connectors(
    state: State<'_, AppState>,
    query: String,
) -> CmdResult<Vec<Connector>> {
    // Before the cache, so removing the key reports the same missing-key error
    // here as in the connected list rather than serving the last session's.
    let key = api_key(&state)?;
    let cache = state.connectors.clone();
    if let Some(hit) = cache.search(&key, &query) {
        return Ok(hit);
    }

    let toolkits = to_string_err(client(&key)?.toolkits(&query).await)?;
    let results: Vec<Connector> = toolkits.into_iter().map(to_connector).collect();
    cache.store_search(&key, query, results.clone());
    Ok(results)
}

/// Starts an OAuth connection and opens the consent page in the browser.
///
/// Composio hosts the callback, so there is nothing to catch here — the user
/// finishes in the browser and the pane picks the new account up on refresh.
#[tauri::command]
#[specta::specta]
pub async fn connect_connector(
    app: AppHandle,
    state: State<'_, AppState>,
    toolkit: String,
) -> CmdResult<()> {
    let url = to_string_err(client(&api_key(&state)?)?.connect(&toolkit).await)?;

    use tauri_plugin_opener::OpenerExt;
    to_string_err(app.opener().open_url(url, None::<&str>).map_err(Into::into))
}

#[tauri::command]
#[specta::specta]
pub async fn disconnect_connector(
    state: State<'_, AppState>,
    connection_id: String,
) -> CmdResult<()> {
    let key = api_key(&state)?;
    to_string_err(client(&key)?.disconnect(&connection_id).await)?;
    // Known-wrong now, so drop it rather than wait for a revalidation to
    // notice. Searches go too: their rows carry the connection state that this
    // call just invalidated.
    state.connectors.clear();
    Ok(())
}

#[tauri::command]
#[specta::specta]
pub fn set_launch_at_login(app: AppHandle, enabled: bool) -> CmdResult<()> {
    use tauri_plugin_autostart::ManagerExt;
    let autolaunch = app.autolaunch();
    let result = if enabled {
        autolaunch.enable()
    } else {
        autolaunch.disable()
    };
    to_string_err(result.map_err(Into::into))
}

/// The last `utterances` dictations, every stage of each, for the dev panel's
/// waterfall. Newest utterance first; stages in start order within one.
#[tauri::command]
#[specta::specta]
pub fn recent_timings(state: State<'_, AppState>, utterances: u32) -> CmdResult<Vec<Span>> {
    let timings = state
        .timings
        .lock()
        .map_err(|_| "timings lock poisoned".to_string())?;
    to_string_err(timings.recent(utterances as usize))
}

/// How long a recording waits for the user before giving up. Long enough to
/// find the key, short enough that a forgotten dialog frees the keyboard —
/// capture swallows every key while armed, so it must never be indefinite.
const CAPTURE_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(10);

/// Records the next key gesture and returns it as a binding.
///
/// Async because it blocks until the user presses something: capture swallows
/// keys while armed, so this owns a `spawn_blocking` thread rather than the
/// main one. Cancelling is `cancel_hotkey_capture`, or simply waiting out
/// [`CAPTURE_TIMEOUT`].
#[tauri::command]
#[specta::specta]
pub async fn capture_hotkey(
    state: State<'_, AppState>,
) -> CmdResult<Option<aloud_hotkey::model::Binding>> {
    let (tx, rx) = std::sync::mpsc::channel();
    // Identifies this request, so its give-up path can tell whether the slot is
    // still its own rather than a later recording's.
    static NEXT_ID: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let id = NEXT_ID.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    {
        let mut slot = state
            .hotkey_capture
            .lock()
            .map_err(|_| "hotkey capture lock poisoned".to_string())?;
        // Replacing an in-flight recording is intentional: opening a second
        // recorder should retarget, not deadlock behind the first.
        *slot = Some(aloud_hotkey::Capture { id, tx });
    }

    let capture = state.hotkey_capture.clone();
    tauri::async_runtime::spawn_blocking(move || {
        let captured = rx.recv_timeout(CAPTURE_TIMEOUT).ok();
        // Disarm on timeout. The listener clears the slot itself on a commit,
        // so this only matters for the give-up path — but leaving it armed
        // would swallow the keyboard indefinitely.
        //
        // Only if the slot is still *ours*. Retargeting drops this task's
        // sender, waking it with Disconnected, which reads as "gave up" — and
        // clearing then disarms the recording that just replaced us. The
        // second row would sit on "Press keys…" while the keys it captured
        // fell through to the matcher and started a real dictation.
        if captured.is_none() {
            if let Ok(mut slot) = capture.lock() {
                if slot.as_ref().is_some_and(|c| c.id == id) {
                    *slot = None;
                }
            }
        }
        captured
    })
    .await
    .map_err(|e| format!("capture task failed: {e}"))
}

/// Disarms a recording the user backed out of.
#[tauri::command]
#[specta::specta]
pub fn cancel_hotkey_capture(state: State<'_, AppState>) -> CmdResult<()> {
    let mut slot = state
        .hotkey_capture
        .lock()
        .map_err(|_| "hotkey capture lock poisoned".to_string())?;
    // Dropping the sender wakes the waiting task, which returns None.
    *slot = None;
    Ok(())
}
